#include <stdio.h>

int main(void)
{
    int values[] = {12, 24, 36};
    int size = 3;
    for (int i = 1; i + 1 < size; i++) {
        values[i] = values[i + 1];
    }
    size--;
    printf("%d %d\n", size, values[1]);
    return 0;
}

